package com.milktea.catalog.service.impl;
import com.milktea.catalog.dto.*; import com.milktea.catalog.entity.*; import com.milktea.catalog.mapper.ProductMapper; import com.milktea.catalog.repository.*; import com.milktea.catalog.service.ProductService; import com.milktea.common.exception.BusinessException; import com.milktea.common.response.PageResponse; import java.math.BigDecimal; import java.util.ArrayList; import java.util.List; import java.util.Map; import java.util.function.Function; import java.util.stream.Collectors; import org.springframework.data.domain.*; import org.springframework.data.jpa.domain.Specification; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service @Transactional(readOnly=true)
public class ProductServiceImpl implements ProductService {
    private final SanPhamRepository products; private final LoaiSanPhamRepository categories; private final BienTheSanPhamRepository variants; private final ProductMapper mapper;
    public ProductServiceImpl(SanPhamRepository products,LoaiSanPhamRepository categories,BienTheSanPhamRepository variants,ProductMapper mapper){this.products=products;this.categories=categories;this.variants=variants;this.mapper=mapper;}
    public PageResponse<ProductResponse> list(Long categoryId,String keyword,Pageable pageable){Specification<SanPham> spec=(root,q,cb)->{List<jakarta.persistence.criteria.Predicate> ps=new ArrayList<>();ps.add(cb.isNull(root.get("deletedAt")));if(categoryId!=null)ps.add(cb.equal(root.get("danhMuc").get("id"),categoryId));if(keyword!=null&&!keyword.isBlank())ps.add(cb.like(cb.lower(root.get("tenSanPham")),"%"+keyword.trim().toLowerCase()+"%"));return cb.and(ps.toArray(jakarta.persistence.criteria.Predicate[]::new));};Page<SanPham> page=products.findAll(spec,pageable);List<SanPham> content=page.getContent();Map<Long,BigDecimal> minimumPrices=minimumPrices(content);return PageResponse.from(page.map(item->toResponse(item,minimumPrices.get(item.getId()))));}
    public ProductResponse get(Long id){SanPham item=product(id);return toResponse(item,minimumPrices(List.of(item)).get(item.getId()));}
    @Transactional public ProductResponse create(ProductRequest r){SanPham p=new SanPham();apply(p,r);return toResponse(products.save(p),null);}
    @Transactional public ProductResponse update(Long id,ProductRequest r){SanPham p=product(id);apply(p,r);return toResponse(p,minimumPrices(List.of(p)).get(p.getId()));}
    @Transactional public void delete(Long id){product(id).markDeleted();}
    private void apply(SanPham p,ProductRequest r){p.setDanhMuc(category(r.maDanhMuc()));p.setTenSanPham(r.tenSanPham().trim());p.setMoTa(r.moTa());p.setHinhAnh(r.hinhAnh());p.setNoiBat(r.noiBat());}
    private Map<Long,BigDecimal> minimumPrices(List<SanPham> items){if(items.isEmpty())return Map.of();return variants.findMinimumPricesByProductIds(items.stream().map(SanPham::getId).toList()).stream().collect(Collectors.toMap(ProductMinPrice::getProductId,ProductMinPrice::getMinPrice));}
    private ProductResponse toResponse(SanPham item,BigDecimal minPrice){ProductResponse mapped=mapper.toResponse(item);return new ProductResponse(mapped.id(),mapped.maDanhMuc(),mapped.tenDanhMuc(),mapped.tenSanPham(),mapped.moTa(),mapped.hinhAnh(),mapped.noiBat(),minPrice,mapped.createdAt(),mapped.updatedAt());}
    private SanPham product(Long id){return products.findById(id).filter(p->p.getDeletedAt()==null).orElseThrow(()->new BusinessException(HttpStatus.NOT_FOUND,"Không tìm thấy sản phẩm"));}
    private LoaiSanPham category(Long id){return categories.findById(id).filter(c->c.getDeletedAt()==null).orElseThrow(()->new BusinessException(HttpStatus.NOT_FOUND,"Không tìm thấy danh mục"));}
}
